<script setup lang="ts">
import {computed} from 'vue'
import {attendanceSummary,type AttendanceCounts} from '../attendance-summary'
const props=defineProps<{totals:AttendanceCounts;group?:boolean}>()
const summary=computed(()=>attendanceSummary(props.totals))
</script>
<template><section class="attendance-summary" aria-label="Saved monthly attendance summary"><div class="summary-metrics"><div><span>Adjusted attendance</span><strong>{{summary.rate===null?'—':summary.rate+'%'}}</strong><small>Of {{summary.counted}} recorded, non-excused {{group?'student-days':'days'}}</small></div><div><span>Adjusted absences</span><strong>{{totals.adjustedAbsences}}</strong><small>{{totals.absent}} absent + {{totals.lateAbsences}} from late marks</small></div><div><span>Recording complete</span><strong>{{summary.coverage===null?'—':summary.coverage+'%'}}</strong><small>{{totals.unmarked}} eligible {{group?'student-days':'days'}} unmarked</small></div></div><p v-if="totals.adjustedAbsences" class="attendance-followup">Review attendance: {{totals.adjustedAbsences}} adjusted {{totals.adjustedAbsences===1?'absence':'absences'}} recorded this month.</p><p v-if="totals.unmarked" class="summary-note">This summary is incomplete until the remaining eligible days are marked.</p><p class="summary-note">Adjusted attendance excludes excused and unmarked days. Every three late marks add one absence per student within the month. Summaries use saved records.</p></section></template>
